-- evt:vat_toad
RegisterEvent(42, "Vat with a toad on its lid", function()
    if not ((not IsPlayerBitSet(PlayerBit(11041)))) then
        evt.StatusText("The brew tastes of mud and does nothing more for you.", 5)
        return
    end
    local r = evt.RandomBetween(1, 7)
    if r == 1 then AddValue(BaseMight, 2)
    elseif r == 2 then AddValue(BaseIntellect, 2)
    elseif r == 3 then AddValue(BasePersonality, 2)
    elseif r == 4 then AddValue(BaseEndurance, 2)
    elseif r == 5 then AddValue(BaseAccuracy, 2)
    elseif r == 6 then AddValue(BaseSpeed, 2)
    else AddValue(BaseLuck, 2) end
    SetPlayerBit(PlayerBit(11041))
    evt.StatusText("It tastes of mud and nettles, and something in you grows stronger. (+2 to one stat, permanent)", 6)
end, "Vat with a toad on its lid")

